import {classifyInterviewRequest} from './interview-assist.mjs';
import {knowledge as seed,hasTerm,sampleResume,sampleJob} from './baseline-engine.mjs';
export {hasTerm,sampleResume,sampleJob};
const internal=(id,title,text,tags)=>({id,title,text,tags,publisher:'Career Compass project framework · authored guidance',url:null,kind:'framework',reviewed:'2026-10-22'});
export const knowledge=[...seed.map(d=>({...d,kind:d.url?'external-summary':'framework',reviewed:'2026-10-22'})),
 internal('requirements','Separate essential and preferred qualifications','Review required skills before preferred skills. A missing mention is a question to investigate, not a finding that the student lacks ability. Degree, experience duration and eligibility statements need manual review.',['resume','requirements']),
 internal('evidence-levels','Distinguish practice from demonstrated work','A skills list is self-reported evidence. A project example adds context, but it still does not independently verify proficiency. A learning intention or an explicit lack of experience should not be treated as demonstrated work.',['resume','skills']),
 internal('negation','Resolve conflicting evidence','If a resume says both that a student lacks a skill and that they used it, clarify the dates and scope. Professional experience and academic exposure may differ. Avoid treating contradictory mentions as a verified match.',['evidence','resume']),
 internal('sql-project','Practice SQL with an explainable project','Choose a small public or synthetic dataset. Write selection, aggregation and join queries to answer a business question. Deliver the query file, a data dictionary, validation checks and a brief explanation of limitations.',['SQL','project','data']),
 internal('python-project','Practice Python with a reproducible analysis','Use a small public or synthetic dataset. Document cleaning decisions, summarize key patterns and validate missing or duplicate values. Deliver a runnable notebook, requirements and an honest discussion of limitations.',['Python','data','project']),
 internal('dashboard-project','Create a dashboard with a purpose','Start with a stakeholder question and define metrics. Build a small dashboard with readable labels and a documented data source. Include data-quality checks and explain which decisions the dashboard can and cannot support.',['Power BI','Tableau','visualization','project']),
 internal('no-experience','Start with academic evidence','When employment experience is limited, use relevant coursework, volunteering, campus leadership or personal projects. Identify your own contribution and label the experience accurately. Do not rename academic work as employment.',['student','resume','experience']),
 internal('star','Use STAR as a story structure','For a behavioral example, state the situation, task, your actions and the result or lesson. Explain decisions and tradeoffs. A result can be qualitative when it is specific and supportable; do not invent a percentage.',['STAR','interview','behavioral']),
 internal('technical-interview','Explain the reasoning behind a technical choice','Describe the problem, constraints, approach, alternatives and validation. If a tool is unfamiliar, explain what you would learn and how you would test your solution. A keyword checklist cannot verify technical correctness.',['interview','technical','SQL','Python']),
 internal('project-story','Build a project story you can defend','Keep a short record of the question, dataset or inputs, methods, personal contribution, checks and outcome. Explain a limitation and what you would do differently. Use only work you can describe in detail.',['interview','project','portfolio']),
 internal('weekly-plan','Set a realistic learning commitment','Choose one priority and a realistic weekly time budget. Scope one project around that budget. Use a deliverable and a self-check for each milestone. Adjust the plan when deadlines or class workload change.',['plan','time','learning']),
 internal('career-exploration','Compare a role through tasks and evidence','Compare responsibilities rather than relying on a job title alone. Pick two example postings, identify recurring tasks and map them to activities you have enjoyed. Ask a career advisor or professional about work you have not experienced.',['career','role','exploration']),
 internal('data-minimization','Share only necessary career information','Use a redacted resume for demonstrations. Omit home address, student identifiers, sensitive personal details and proprietary employer material. Downloaded exports may contain personal information and need appropriate handling.',['privacy','resume']),
 internal('evaluation','Evaluate a coach with cases and human feedback','Use varied student examples, check cited evidence and record failures. Separate automated rule checks from actual student usefulness. Do not invent user feedback, model performance, costs or latency measurements.',['evaluation','quality'])];
const stop=new Set('the a an to of and in for with on is are be or as by from this that you your our we will have at it not can'.split(' '));
export function tokenize(s){return String(s).toLowerCase().match(/[a-z0-9+#]+/g)?.filter(x=>!stop.has(x)).map(x=>({practicing:'practice',interviews:'interview',resumes:'resume',skills:'skill',projects:'project'}[x]||x))||[]}
export function retrieve(query,docs=knowledge,limit=3){const expanded=query+' '+(/\bcv\b/i.test(query)?' resume':'')+(/\bstar\b/i.test(query)?' interview behavioral':'');const terms=[...new Set(tokenize(expanded))];const tokens=docs.map(d=>tokenize(d.title+' '+d.text+' '+(d.tags||[]).join(' ')));const avg=tokens.reduce((s,t)=>s+t.length,0)/(tokens.length||1);return docs.map((d,i)=>{let score=0;for(const term of terms){const tf=tokens[i].filter(t=>t===term).length;if(!tf)continue;const df=tokens.filter(t=>t.includes(term)).length;score+=Math.log(1+(docs.length-df+.5)/(df+.5))*tf*2.2/(tf+1.2*(.25+.75*tokens[i].length/(avg||1)))}score*=1+terms.filter(term=>tokens[i].includes(term)).length/Math.max(1,terms.length);return {...d,score}}).filter(d=>d.score>0).sort((a,b)=>b.score-a.score).slice(0,limit)}
export const catalog={SQL:['sql','mysql','postgresql','sqlite'],Python:['python','pandas','numpy'],Excel:['excel','spreadsheets','vlookup','pivot tables'],Tableau:['tableau'],'Power BI':['power bi','powerbi'],'Data analysis':['data analysis','data analytics','analyzing data',/analy[sz](?:ed|ing|e).{0,45}\b(data|records|dataset|survey|sales)\b/i],'Data visualization':['data visualization','visualisation','visualization','dashboard','dashboards','charts'],Statistics:['statistics','statistical'],'Machine learning':['machine learning','scikit-learn'],Communication:['communication','presentations','presented','communicate','stakeholder presentation'],Teamwork:['teamwork','collaborated','collaboration','team player',/worked (?:with|in|as part of) (?:a |the |my )?team/i],Leadership:['leadership','led a team','team lead','led a group'],'Project management':['project management','project planning'],Agile:['agile','scrum'],'Requirements gathering':['requirements gathering','business requirements','requirements analysis','gathering requirements'],JavaScript:['javascript','typescript'],React:['react','reactjs'],HTML:['html'],CSS:['css'],Java:['java'],Git:['git','github','version control'],AWS:['aws','amazon web services'],APIs:['api','apis','rest api'],Marketing:['marketing'],'Customer research':['customer research','user research'],Finance:['finance','financial analysis'],Accounting:['accounting'],Writing:['writing','copywriting','written'],Sales:['sales'],Design:['figma','ux','ui design'],RAG:['rag','retrieval augmented','retrieval-augmented'],AI:['ai','artificial intelligence','generative ai'],Docker:['docker'],Kubernetes:['kubernetes'],'C++':['c++'],'C#':['c#']};
const segments=text=>String(text).split(/\n|(?<=[.!?;])\s+/).map(x=>x.trim()).filter(Boolean);
const match=(s,aliases)=>aliases.some(a=>a instanceof RegExp?a.test(s):hasTerm(s,a));
const concrete=/\b(built|created|analy[sz]ed|developed|designed|implemented|tested|wrote|maintained|presented|collaborated|led|organized|resolved|cleaned|queried|used)\b/i;
function classify(text,aliases){const lines=segments(text).flatMap(line=>line.split(/\bbut\b|\bhowever\b/i)).filter(s=>match(s,aliases));const entries=lines.map(s=>{const neg= /^\s*not (?!only\b)/i.test(s)||/\b(no (?:\w+ )?(?:experience|knowledge|skills?|exposure)|without (?:\w+ )?(?:experience|knowledge)|lack(?:ing)? (?:\w+ )?(?:experience|knowledge)|never used|not (?:yet )?(?:familiar|experienced|proficient)|unfamiliar|haven't (?:used|learned)|have not (?:used|learned)|do not know|don't know)\b/i.test(s);const learning=/\b(learning|beginner|currently studying|plan to learn|want to learn|introductory|basic familiarity)\b/i.test(s);return {text:s,status:neg?'explicit-gap':learning?'learning':concrete.test(s)?'example':'listed'}});const positive=entries.filter(e=>['example','listed'].includes(e.status));const negative=entries.filter(e=>e.status==='explicit-gap');let status=!entries.length?'not-mentioned':negative.length&&positive.length?'needs-clarification':negative.length?'explicit-gap':positive.some(e=>e.status==='example')?'example':positive.length?'listed':'learning';const selected=entries.find(e=>e.status===status)||entries[0];return {status,text:selected?.text.slice(0,600)||'',entries}}
export const statusLabels={'example':'Example described','listed':'Self-reported skill','learning':'Learning / introductory','explicit-gap':'Explicit experience gap','needs-clarification':'Needs clarification','not-mentioned':'Not mentioned'};
function jobRequirements(job,aliases){let heading='unspecified';const out=[];for(const line of segments(job)){if(/^(preferred|nice.to.have|desired|bonus)( qualifications| skills| requirements)?\s*:?$/i.test(line))heading='preferred';else if(/^(required|essential|minimum|must.have)( qualifications| skills| requirements)?\s*:?$/i.test(line))heading='required';else if(/^(responsibilities|duties|about|benefits)\s*:?$/i.test(line))heading='unspecified';if(match(line,aliases)){const priority=/\b(not required|optional|preferred|nice.to.have|bonus|desired)\b/i.test(line)?'preferred':/\b(required|must|essential|minimum)\b/i.test(line)?'required':heading;out.push({text:line.slice(0,600),priority})}}return out}
export function analyze(resume,job,role,docs=knowledge){if(resume.trim().length<40||job.trim().length<40)throw Error('Add at least 40 characters to both your resume and job description.');if(resume.length>40000||job.length>40000)throw Error('Keep each input below 40,000 characters.');const rows=[];for(const [skill,aliases]of Object.entries(catalog)){const reqs=jobRequirements(job,aliases);if(!reqs.length)continue;const r=classify(resume,aliases);const priority=reqs.some(r=>r.priority==='required')?'required':reqs.some(r=>r.priority==='preferred')?'preferred':'unspecified';rows.push({skill,found:['example','listed'].includes(r.status),status:r.status,priority,resumeEvidence:r.text,jobEvidence:reqs.map(r=>r.text).join('\n'),explanation:r.status==='not-mentioned'?'No recognized evidence found. Ask the student before assuming a skill gap.':r.status==='needs-clarification'?'Both positive and negative evidence appear. Confirm context and dates.':r.status==='learning'?'Learning intent is not demonstrated proficiency.':r.status==='listed'?'Listed by the student; add a concrete example if available.':r.status==='explicit-gap'?'The student explicitly reports limited or no experience.':'An example is described; proficiency is not independently verified.'})}rows.sort((a,b)=>({required:0,unspecified:1,preferred:2}[a.priority]-{required:0,unspecified:1,preferred:2}[b.priority]));const found=rows.filter(r=>r.found),gaps=rows.filter(r=>!r.found);const manualReview=segments(job).filter(s=>/\b(\d+\+?\s*(?:years?|yrs?)|bachelor|master|degree|work authorization|visa|citizen|clearance)\b/i.test(s)).slice(0,8);return {role:role.trim()||'Your target role',rows,found,gaps,manualReview,sources:retrieve('resume evidence '+gaps.map(g=>g.skill).join(' '),docs),coverage:rows.length?Math.round(found.length/rows.length*100):null,notes:['Rule-based comparison with phrase aliases and limited negation handling; no language model is connected.','Coverage includes self-reported skills and described examples. It is not proficiency, an ATS score or a hiring probability.','Negation scope, mixed sentences, synonyms and required/preferred headings can still be misread. Review source excerpts.','Degree, eligibility and experience-duration requirements are shown for manual review; they are not adjudicated.'],trace:[{tool:'Read inputs',detail:`Read ${resume.length} resume characters and ${job.length} job-description characters.`},{tool:'Classify evidence',detail:`Classified ${rows.length} skills as described, listed, learning, absent, explicitly missing or unclear.`},{tool:'Retrieve guidance',detail:`BM25 ranked ${docs.length} passages and returned source IDs: ${retrieve('resume evidence '+gaps.map(g=>g.skill).join(' '),docs).map(d=>d.id).join(', ')}.`},{tool:'Return structured result',detail:'Deterministic tool pipeline. Model-driven agent selection and grounded generation are pending.'}]}}
const projects={SQL:'Write and validate five SQL queries, including a join and an aggregation, against a small public or synthetic dataset.',Python:'Create a reproducible Python notebook with cleaning decisions, data-quality checks and one answer to a business question.','Power BI':'Build a Power BI dashboard with three defined measures, a documented data source and a short explanation of one decision it supports.',Tableau:'Build a Tableau dashboard with clear labels, a stakeholder question and a documented data source.','Data analysis':'Analyze a small dataset, document cleaning choices and write a one-page findings note.','Data visualization':'Create three charts answering a specific question and explain why each chart type fits.','Requirements gathering':'Write a one-page requirements brief with a stakeholder, problem, acceptance criteria and unresolved questions.',Agile:'Create a small project backlog with user stories, acceptance criteria and a short retrospective.',Communication:'Prepare a three-minute project explanation for a nontechnical classmate and request specific feedback.',Teamwork:'Complete a small paired task and document how responsibilities, decisions and disagreements were handled.'};
export function makePlan(result,profile={}){const focus=result.gaps.find(g=>g.priority==='required')||result.gaps[0];const skill=focus?.skill||result.found[0]?.skill||'your most relevant project';const hours=Math.max(1,Math.min(20,Number(profile.hoursPerWeek)||3));return [{week:'Week 01',title:'Confirm the evidence',text:`Budget about ${hours} hours this week. Review ${skill} evidence and any degree or experience requirements. Add truthful examples you already have before choosing what to study.`,deliverable:'Two revised bullets and a confirmed priority skill.',check:'Every claim maps to a real example you can explain.'},{week:'Week 02',title:'Build a focused proof point',text:(projects[skill]||`Choose one small task involving ${skill} from the target job. Produce a concrete artifact and document how you checked it.`)+` Scope it to about ${hours} hours.`,deliverable:'A small artifact plus validation checks.',check:'Someone else can follow the method and understand the limits.'},{week:'Week 03',title:'Explain your contribution',text:'Write a short case study: question, inputs, your actions, validation, result and one limitation. Label academic or personal work accurately.',deliverable:'A one-page project story.',check:'Distinguish personal work from team work; use only verifiable outcomes.'},{week:'Week 04',title:'Practice and seek feedback',text:`Practice three answers for ${result.role}. Tailor one application and ask a peer or career advisor to identify unclear or unsupported claims.`,deliverable:'A tailored application and three practice answers.',check:'Record real feedback and one resulting revision.'}]}
export function questions(result){const skill=result?.found?.find(x=>x.status==='example')?.skill||result?.found?.[0]?.skill||'a relevant skill';return [`Tell me about a project that prepares you for ${result?.role||'your target role'}. What was your contribution?`,'Describe a time your team disagreed. What options did you consider, and what did you personally do?',`Explain a decision you made while using ${skill}. What alternatives did you consider and how did you validate the result?`,'Describe a difficult problem. What evidence changed your approach, and what limitation remained?','What would you ask the interviewer about success measures, training, and the responsibilities of this role?']}
export function interviewFeedback(answer){const words=answer.trim().split(/\s+/).filter(Boolean);const concreteObject=/\b(dashboard|query|queries|dataset|records|customer|survey|application|prototype|report|spreadsheet|database|campaign|schedule|budget|event|stakeholder|analysis|notebook|test|model|presentation)\b/i.test(answer);const substance=words.length>=18&&concreteObject;const action=/\bI\s+(?:(?:personally|then|also)\s+)?(?:built|analy[sz]ed|created|led|organized|decided|tested|designed|wrote|developed|resolved|queried|cleaned|validated|compared)\b/i.test(answer);const outcome=/\b(result|learned|improved|reduced|increased|completed|delivered|helped|found)\b/i.test(answer)&&(/\b(\d+\s*(?:records|hours|users|students|queries|percent|%|days|rows)|because|by |that |which |how |review|validate|deliver)\b/i.test(answer)||words.length>=55);const items=[{label:'Context',tip:'Name the specific project, problem and constraint.',signal:substance&&/project|during|when|team|class|internship|client/i.test(answer)},{label:'Your actions',tip:'Explain your personal action, method and reason for choosing it.',signal:substance&&action},{label:'Outcome',tip:'Explain a specific verified result or lesson. A number alone is not evidence.',signal:substance&&outcome}];const followUp=!substance?'What specific artifact or problem did you work on, and what did you personally change?':!action?'What did you personally do, rather than the team as a whole?':!outcome?'What happened as a result, and how did you verify or learn it?':/because|instead|alternative|trade.off/i.test(answer)?'What limitation remained, and what would you change next time?':'Why did you choose that approach over an alternative?';return {words:words.length,items,followUp,note:'Rule-based structure signals only. They do not establish answer quality or verify truth, technical correctness or employability.'}}
export function reviewResume(resume){const lines=segments(resume);const candidates=lines.filter(s=>concrete.test(s)||/worked on|responsible for|helped with/i.test(s)).slice(0,4);return {checks:[{label:'Education or academic context',present:/university|college|degree|bachelor|master|\bMS\b|\bBS\b|coursework/i.test(resume)},{label:'Project or work example',present:candidates.length>0},{label:'Skills named',present:/skills|SQL|Python|Excel|Tableau|Java|marketing|design/i.test(resume)},{label:'Scope or outcome evidence',present:/\d|improved|reduced|delivered|learned|result/i.test(resume)}],bullets:candidates.map(s=>({original:s,draft:s.replace(/^[-•*]\s*/,'').replace(/^worked on\b/i,'Contributed to').replace(/^helped with\b/i,'Contributed to'),questions:[...(!/\bI\b|my|independently/i.test(s)?['What was your individual contribution?']:[]),...(!/\d|result|improved|reduced|delivered/i.test(s)?['What outcome or scope can you substantiate?']:[])],template:'[Your action] + [specific task] + [method/tool] + [verified scope, outcome, or lesson].'})),note:'Edits only remove bullet markers or replace “worked on/helped with” with “contributed to”. Bracketed prompts are questions, not invented achievements.'}}
export function routeIntent(text){const s=text.trim().toLowerCase();const interview=classifyInterviewRequest(text);if(interview)return interview.intent;if(s.length>140)return null;if(/resume|\bcv\b/.test(s)&&/review|improve|check|feedback|stronger/.test(s))return 'resume';if(/skill|gap|evidence/.test(s)&&/show|find|what|review|insight/.test(s))return 'gaps';if(/plan|next steps/.test(s))return 'plan';if(/source|citation|guidance/.test(s)&&/show|see|where|what/.test(s))return 'sources';return null}
